    return '<span class="visual-label">BUNGALOW OS / OPERATIONS</span><span class="ops-preview"><span class="ops-header"><img src="'+p.image+'" alt="" loading="lazy">'+t('opsTitle')+'</span><span class="ops-layout"><span class="ops-sidebar"><span>'+t('ops1')+'</span><span>'+t('ops2')+'</span><span>'+t('ops3')+'</span></span><span class="ops-calendar">'+Array.from({length:21},()=>'<span></span>').join('')+'</span></span><span class="ops-footer"><span></span><span></span><span></span></span></span>'+caption;
