  function renderFeatured(){document.getElementById('featured-projects').innerHTML=projects.filter(p=>p.featured).map(p=>'<article class="feature-card"><button type="button" class="feature-visual '+p.id+'-visual" data-project="'+p.id+'" aria-label="'+esc(t('details')+': '+p.name)+'">'+featuredVisual(p)+'<span class="visual-open" aria-hidden="true">↗</span></button><div class="feature-info"><div><p class="feature-tag">'+esc(p[lang].tag)+'</p><button type="button" class="feature-title-button" data-project="'+p.id+'"><h3>'+esc(p.name)+'</h3></button><p class="feature-summary">'+esc(p[lang].summary)+'</p></div>'+badge(p)+'</div></article>').join('');}
  function normalise(value){return Array.from(value.toLocaleLowerCase(lang==='tr'?'tr-TR':'en').normalize('NFD')).filter(c=>{const p=c.codePointAt(0);return p<0x300||p>0x36f;}).join('').replace(/ı/g,'i');}
  function renderGrid(){const q=normalise(query.trim());const list=projects.filter(p=>(filter==='all'||p.category===filter)&&(!q||normalise([p.name,p[lang].description,p[lang].tag,...p.stack].join(' ')).includes(q)));const visible=list.slice(0,limit);document.getElementById('project-grid').innerHTML=visible.map(p=>'<article class="project-card"><div class="project-card-top"><span class="project-index">'+String(projects.indexOf(p)+1).padStart(2,'0')+' / '+esc(p[lang].tag.split(' / ')[0])+'</span>'+badge(p)+'</div><h3>'+esc(p.name)+'</h3><p class="card-description">'+esc(p[lang].description)+'</p>'+stack(p)+'<button type="button" class="card-action" data-project="'+p.id+'" aria-label="'+esc(t('workDetails')+': '+p.name)+'"><span>'+t('workDetails')+'</span><span aria-hidden="true">↗</span></button></article>').join('');document.getElementById('result-count').textContent=visible.length+' / '+list.length+' '+t('cardCount');document.getElementById('no-results').hidden=list.length!==0;document.getElementById('show-more').hidden=visible.length>=list.length;}
  function renderDialog(p){const c=p[lang];document.getElementById('dialog-content').innerHTML='<div class="dialog-heading"><h2 id="dialog-title">'+esc(p.name)+'</h2>'+badge(p)+'</div><p class="dialog-category">'+esc(c.tag)+'</p><p class="dialog-description">'+esc(c.description)+'</p>'+stack(p)+(c.capabilities?'<div class="dialog-capabilities">'+c.capabilities.map(s=>'<span>'+esc(s)+'</span>').join('')+'</div>':'')+(p.image?'<figure class="dialog-visual"><img src="'+p.image+'" alt="'+esc(c.visual||p.name)+'"><figcaption>'+esc(c.visual||'')+'</figcaption></figure>':'')+'<div class="dialog-section"><h3>'+t('problem')+'</h3><p>'+esc(c.problem)+'</p></div><div class="dialog-section"><h3>'+t('approach')+'</h3><p>'+esc(c.approach)+'</p></div><div class="dialog-section"><h3>'+t('scope')+'</h3><p>'+esc(c.scope)+'</p></div><div class="dialog-links">'+(p.androidTest?'<a class="button button-primary" href="'+esc(p.androidTest)+'" target="_blank" rel="noopener noreferrer"><span>'+t('androidTest')+'</span><span aria-hidden="true">↗</span></a>':'')+(p.androidGuide?'<a class="button button-secondary" href="'+esc(p.androidGuide)+'" target="_blank" rel="noopener noreferrer"><span>'+t('androidGuide')+'</span><span aria-hidden="true">↗</span></a>':'')+(p.live?'<a class="button button-primary" href="'+p.live+'" target="_blank" rel="noopener noreferrer"><span>'+t('openWeb')+'</span><span aria-hidden="true">↗</span></a>':'')+(p.repo?'<a class="button button-primary" href="'+p.repo+'" target="_blank" rel="noopener noreferrer"><span>'+t('openCode')+'</span><span aria-hidden="true">↗</span></a>':'')+'<a class="button button-secondary" href="mailto:voyagerroc@voyagerroctechnologies.com?subject='+encodeURIComponent('Voyagerroc Technologies / '+p.name)+'"><span>'+t('askProject')+'</span><span aria-hidden="true">↗</span></a></div><p class="dialog-fineprint">'+t('checked')+'</p>';}
  function openProject(id,updateURL=true){const p=projects.find(p=>p.id===id);if(!p)return;if(!dialog.open){returnFocus=document.activeElement;previousHash=location.hash.startsWith('#project/')?'':location.hash;}activeProject=p;renderDialog(p);if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';document.querySelector('.dialog-close').focus();if(updateURL&&location.hash!=='#project/'+p.id)history.pushState(null,'','#project/'+p.id);}
  function closeProject(updateURL=true){if(dialog.open)dialog.close();activeProject=null;document.body.style.overflow='';if(updateURL&&location.hash.startsWith('#project/'))history.replaceState(null,'',previousHash||location.pathname+location.search);if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});}
  function syncHash(){if(location.hash.startsWith('#project/'))openProject(location.hash.slice(9),false);else if(dialog.open)closeProject(false);}
  function setLanguage(next,persist=true){lang=next==='en'?'en':'tr';document.documentElement.lang=lang;document.title=lang==='tr'?'Voyagerroc Technologies — Gerçek ihtiyaçlar. Güçlü sistemler.':'Voyagerroc Technologies — Real needs. Powerful systems.';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('[data-i18n-html]').forEach(el=>el.innerHTML=t(el.dataset.i18nHtml));document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));const search=document.getElementById('project-search');search.placeholder=t('search');search.setAttribute('aria-label',t('search'));document.querySelector('.dialog-close').setAttribute('aria-label',t('close'));document.querySelector('.main-nav').setAttribute('aria-label',t('navLabel'));document.querySelector('.filters').setAttribute('aria-label',t('filterLabel'));document.querySelector('#scene-container').setAttribute('aria-label',t('sceneAria'));const mt=document.getElementById('method-toggle');mt.textContent=t(mt.getAttribute('aria-expanded')==='true'?'methodClose':'methodLabel');renderFeatured();renderGrid();if(activeProject)renderDialog(activeProject);window.dispatchEvent(new CustomEvent('portfolio:language',{detail:lang}));if(persist){try{sessionStorage.setItem('voyagerroc-lang',lang);}catch{}}}
  document.addEventListener('click',event=>{const pb=event.target.closest('[data-project]');if(pb){openProject(pb.dataset.project);return;}const lb=event.target.closest('[data-lang]');if(lb){setLanguage(lb.dataset.lang);return;}const fb=event.target.closest('[data-filter]');if(fb){filter=fb.dataset.filter;limit=9;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===fb);b.setAttribute('aria-pressed',String(b===fb));});renderGrid();}});
  document.querySelectorAll('.radar-row').forEach(row=>row.addEventListener('pointerenter',()=>window.dispatchEvent(new CustomEvent('portfolio:product-focus',{detail:row.dataset.project}))));
