  document.getElementById('show-more').addEventListener('click',()=>{const prior=[...document.querySelectorAll('#project-grid [data-project]')].length;limit=projects.length;renderGrid();document.querySelectorAll('#project-grid [data-project]')[prior]?.focus({preventScroll:true});});
  document.querySelector('.dialog-close').addEventListener('click',()=>closeProject());dialog.addEventListener('cancel',e=>{e.preventDefault();closeProject();});dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProject();});
  const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('main-nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}));
  document.getElementById('method-toggle').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));document.getElementById('method-note').hidden=!open;e.currentTarget.textContent=t(open?'methodClose':'methodLabel');});
